=>20000],  ['fuel_type'=>'XTRA UNL',  'label'=>'XTRA UNL 2 - 4',  'tank'=>'Underground Tank #17', 'tanker_num'=>17, 'capacity'=>20000],
];  // ── AJAX Handler ─────────────────────────────────────────────────────
if (isset($_GET['ajax']) && ($_GET['action'] ?? '') === 'get_fuel_details') {  header('Content-Type: application/json');  $fuel_type = $_GET['fuel_type'] ?? '';  $deliveries = [];  try {  $stmt = $pdo->prepare("SELECT delivery_date, delivery_liters, invoice_no, supplier, status FROM fuel_deliveries WHERE station_id = ? AND LOWER(fuel_type) = LOWER(?) ORDER BY delivery_date DESC, id DESC LIMIT 10");  $stmt->execute([$station_id, $fuel_type]);  $deliveries = $stmt->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) {}  $transactions = [];  try {  $stmt = $pdo->prepare("SELECT transaction_date, liters_sold, total_amount, shift_period, status FROM fuel_transactions WHERE station_id = ? AND LOWER(fuel_type) = LOWER(?) ORDER BY transaction_date DESC, id DESC LIMIT 10");  $stmt->execute([$station_id, $fuel_type]);  $transactions = $stmt->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) {}  echo json_encode([  'success' => true,  'deliveries' => $deliveries,  'transactions' => $transactions  ]);  exit;
}  // ── Fetch DB data for current calculations ────────────────────────────
$fi_lookup = [];
try {  $s = $pdo->prepare("SELECT id, fuel_type, current_level, current_stock, capacity, price_per_liter, latest_calibration, status, last_updated, reorder_level FROM fuel_inventory WHERE station_id = ?");  $s->execute([$station_id]);  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $row) {  $fi_lookup[strtolower(trim($row['fuel_type']))] = $row;  }
} catch (Exception $e) {}  $del_lookup = [];
try {  $s = $pdo->prepare("SELECT tank_assigned, fuel_type, SUM(delivery_liters) AS total_del FROM fuel_deliveries WHERE station_id = ? AND DATE(delivery_date) = CURDATE() AND status = 'Verified' GROUP BY tank_assigned, fuel_type");  $s->execute([$station_id]);  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $row) {  $del_lookup[strtolower(trim($row['tank_assigned']))] = (float)$row['total_del'];  }
} catch (Exception $e) {}  $sales_lookup = [];
try {  $s = $pdo->prepare("SELECT fuel_type, SUM(liters_sold) AS total_sales FROM fuel_transactions WHERE station_id = ? AND DATE(transaction_date) = CURDATE() AND status = 'Verified' GROUP BY fuel_type");  $s->execute([$station_id]);  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $row) {  $sales_lookup[strtolower(trim($row['fuel_type']))] = (float)$row['total_sales'];  }
} catch (Exception $e) {}  $adj_lookup = [];
try {  $s = $pdo->prepare("SELECT fi.fuel_type, COALESCE(SUM(fa.liters),0) AS total_adj FROM fuel_adjustments fa JOIN fuel_inventory fi ON fa.fuel_type_id = fi.fuel_type_id AND fi.station_id = fa.station_id WHERE fa.station_id = ? AND DATE(fa.adjustment_date) = CURDATE() GROUP BY fi.fuel_type");  $s->execute([$station_id]);  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $row) {  $adj_lookup[strtolower(trim($row['fuel_type']))] = (float)$row['total_adj'];  }
} catch (Exception $e) {}  $price_lookup = [];
try {  $s = $pdo->prepare("SELECT ft.name AS fuel_type, fp.price_per_liter FROM fuel_pricing fp JOIN fuel_types ft ON fp.fuel_type_id = ft.id WHERE fp.station_id = ? AND fp.is_active = 1 ORDER BY fp.effective_date DESC");  $s->execute([$station_id]);  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $row) {  $key = strtolower(trim($row['fuel_type']));  if (!isset($price_lookup[$key])) $price_lookup[$key] = (float)$row['price_per_liter'];  }
} catch (Exception $e) {}  // ── Process tanks dataset ─────────────────────────────────────────────
$rows = [];
$total_fuel_volume = 0;  foreach ($TANK_CONFIG_17 as $tc) {  $ft_key  = strtolower(trim($tc['fuel_type']));  if ($ft_key === 'xtra unl') {  if (strpos(strtolower($tc['label']), 'xtra unl 1') !== false) {  $ft_key = 'xtra unl 1';  } elseif (strpos(strtolower($tc['label']), 'xtra unl 2') !== false) {  $ft_key = 'xtra unl 2';  }  }  $tank_key = strtolower(trim($tc['tank']));  $inv  = $fi_lookup[$ft_key] ?? null;  $capacity  = (float)$tc['capacity'];  $cur_level = $inv ? (float)($inv['current_level'] ?? $inv['current_stock'] ?? 0) : 0;  $same_type_count = count(array_filter($TANK_CONFIG_17, function($t) use ($ft_key) {  $k = strtolower(trim($t['fuel_type']));  if ($k === 'xtra unl') {  if (strpos(strtolower($t['label']), 'xtra unl 1') !== false) {  $k = 'xtra unl 1';  } elseif (strpos(strtolower($t['label']), 'xtra unl 2') !== false) {  $k = 'xtra unl 2';  }  }  return $k === $ft_key;  }));  $purchases = $del_lookup[$tank_key] ?? 0;  $sales_total = $sales_lookup[$ft_key] ?? 0;  $adj_total  = $adj_lookup[$ft_key] ?? 0;  $sales  = $same_type_count > 0 ? round($sales_total / $same_type_count, 2) : 0;  $calibration = $same_type_count > 0 ? round($adj_total / $same_type_count, 2) : 0;  $beginning = $same_type_count > 0 ? round($cur_level / $same_type_count, 2) : 0;  $total_available = $beginning + $purchases;  $ending_system  = max(0, $total_available - $sales - $calibration);  $remaining_capacity = max(0, $capacity - $ending_system);  $total_fuel_volume += $ending_system;  $fill_pct = $capacity > 0 ? ($ending_system / $capacity) * 100 : 0;  if ($ending_system <= 0) {  $status = 'Out of Stock';  $sc = '#dc3545';  } elseif ($fill_pct <= 10) {  $status = 'Critical';  $sc = '#dc3545';  } elseif ($fill_pct <= 25) {  $status = 'Low';  $sc = '#fd7e14';  } else {  $status = 'Normal';  $sc = '#28a745';  }  $price = $price_lookup[$ft_key] ?? ($inv ? (float)($inv['price_per_liter'] ?? 0) : 0);  $timestamp = $inv['last_updated'] ?? null;  $rows[] = [  'tank_id'  => $tc['tanker_num'],  'tank_name'  => $tc['label'],  'tank_description'  => $tc['tank'],  'fuel_type'  => $tc['fuel_type'],  'capacity'  => $capacity,  'current_volume'  => $ending_system,  'remaining_capacity' => $remaining_capacity,  'status'  => $status,  'status_color'  => $sc,  'last_updated'  => $timestamp,  'price'  => $price  ];
