if (!in_array($active_tab, ['overview', 'alerts', 'movement'])) {  $active_tab = 'overview';
}  $alert_rows = [];
foreach ($rows as $r) {  if (in_array($r['status'], ['Low', 'Critical', 'Out of Stock'])) {  $ft_key = strtolower(trim($r['fuel_type']));  if ($ft_key === 'xtra unl') {  if (strpos(strtolower($r['tank_name']), 'xtra unl 1') !== false) {  $ft_key = 'xtra unl 1';  } elseif (strpos(strtolower($r['tank_name']), 'xtra unl 2') !== false) {  $ft_key = 'xtra unl 2';  }  }  $inv = $fi_lookup[$ft_key] ?? null;  $same_type_count = count(array_filter($TANK_CONFIG_17, function($t) use ($ft_key) {  $k = strtolower(trim($t['fuel_type']));  if ($k === 'xtra unl') {  if (strpos(strtolower($t['label']), 'xtra unl 1') !== false) {  $k = 'xtra unl 1';  } elseif (strpos(strtolower($t['label']), 'xtra unl 2') !== false) {  $k = 'xtra unl 2';  }  }  return $k === $ft_key;  }));  $reorder_level_per_tank = $inv ? (float)$inv['reorder_level'] / $same_type_count : 0.25 * $r['capacity'];  if ($r['status'] === 'Out of Stock' || $r['current_volume'] <= 0) {  $alert_type = 'Empty Tank';  $recommended_action = 'Urgent Refill Required - Tank Empty';  } elseif ($r['status'] === 'Critical') {  $alert_type = 'Critical Fuel';  $recommended_action = 'Critical Depletion Warning - Refill Immediately';  } else {  $alert_type = 'Low Fuel';  $recommended_action = 'Initiate Delivery Request';  }  $alert_rows[] = array_merge($r, [  'reorder_level' => $reorder_level_per_tank,  'alert_type' => $alert_type,  'recommended_action' => $recommended_action  ]);  }
}
$total_alert_tanks = count($alert_rows);  $alert_low_tanks = count(array_filter($rows, fn($r) => $r['status'] === 'Low'));
$alert_critical_tanks = count(array_filter($rows, fn($r) => $r['status'] === 'Critical'));
$alert_empty_tanks = count(array_filter($rows, fn($r) => $r['status'] === 'Out of Stock' || $r['current_volume'] <= 0));
$alert_needing_delivery = $alert_low_tanks + $alert_critical_tanks + $alert_empty_tanks;  // ── Fuel Movement History Data (only fetched when on movement tab) ─────
$mov_rows  = [];
$mov_total  = 0;
$mov_deliveries  = 0;
$mov_sales  = 0;
$mov_adjustments  = 0;  if ($active_tab === 'movement') {  // Deliveries  try {  $s = $pdo->prepare("  SELECT  CONCAT('DEL-', fd.id)  AS movement_id,  fd.delivery_date  AS movement_date,  fd.fuel_type,  COALESCE(fd.tank_assigned,'—') AS tank,  'Delivery'  AS movement_type,  fd.delivery_liters  AS liters,  NULL  AS previous_volume,  NULL  AS new_volume,  COALESCE(u.name,'—')  AS performed_by,  fd.invoice_no  AS ref_no,  fd.status,  fd.notes  FROM fuel_deliveries fd  LEFT JOIN users u ON fd.received_by = u.id  WHERE fd.station_id = ?  ORDER BY fd.delivery_date DESC, fd.id DESC  LIMIT 200  ");  $s->execute([$station_id]);  $del_rows = $s->fetchAll(PDO::FETCH_ASSOC);  $mov_deliveries = count($del_rows);  $mov_rows = array_merge($mov_rows, $del_rows);  } catch (Exception $e) {}  // Sales  try {  $s = $pdo->prepare("  SELECT  CONCAT('SAL-', ft.id)  AS movement_id,  DATE(ft.transaction_date)  AS movement_date,  ft.fuel_type,  COALESCE(CONCAT('Pump #',ft.pump_id),'—') AS tank,  'Sale'  AS movement_type,  ft.liters_sold  AS liters,  NULL  AS previous_volume,  NULL  AS new_volume,  COALESCE(u.name,'—')  AS performed_by,  ft.transaction_id  AS ref_no,  ft.status,  ft.notes  FROM fuel_transactions ft  LEFT JOIN users u ON ft.staff_id = u.id  WHERE ft.station_id = ?  ORDER BY ft.transaction_date DESC, ft.id DESC  LIMIT 200  ");  $s->execute([$station_id]);  $sale_rows = $s->fetchAll(PDO::FETCH_ASSOC);  $mov_sales = count($sale_rows);  $mov_rows = array_merge($mov_rows, $sale_rows);  } catch (Exception $e) {}  // Adjustments  try {  $s = $pdo->prepare("  SELECT  CONCAT('ADJ-', fa.id)  AS movement_id,  fa.adjustment_date  AS movement_date,  fa.fuel_type,  '—'  AS tank,  CONCAT('Adjustment (',fa.adjustment_type,')') AS movement_type,  fa.liters,  fa.previous_value  AS previous_volume,  fa.new_value  AS new_volume,  COALESCE(u.name,'—')  AS performed_by,  fa.reason  AS ref_no,  fa.status,  fa.notes  FROM fuel_adjustments fa  LEFT JOIN users u ON fa.user_id = u.id  WHERE fa.station_id = ?  ORDER BY fa.adjustment_date DESC, fa.id DESC  LIMIT 200  ");  $s->execute([$station_id]);  $adj_rows = $s->fetchAll(PDO::FETCH_ASSOC);  $mov_adjustments = count($adj_rows);  $mov_rows = array_merge($mov_rows, $adj_rows);  } catch (Exception $e) {}  // Sort combined rows by date desc  usort($mov_rows, function($a, $b) {  return strcmp($b['movement_date'], $a['movement_date']);  });  $mov_total = count($mov_rows);
