<div class="modal-overlay" id="movementModal">  <div class="modal-box" style="width:750px;">  <div class="modal-header">  <h3 id="movementModalTitle">Fuel Movement History</h3>  </div>  <div class="modal-body" style="padding:0;">  <div style="display:flex;border-bottom:2px solid #e2e8f0;background:#f8fafc;padding:0 10px;">  <button class="modal-tab-btn active" id="tabDelBtn" onclick="switchMovTab('deliveries')" style="padding:12px 16px;border:none;background:none;font-weight:700;font-size:12px;text-transform:uppercase;color:#002F70;border-bottom:2px solid #002F70;cursor:pointer;display:flex;align-items:center;gap:6px;"><i class="fas fa-truck"></i> Deliveries</button>  <button class="modal-tab-btn" id="tabSalesBtn" onclick="switchMovTab('sales')" style="padding:12px 16px;border:none;background:none;font-weight:700;font-size:12px;text-transform:uppercase;color:#64748b;border-bottom:2px solid transparent;cursor:pointer;display:flex;align-items:center;gap:6px;"><i class="fas fa-receipt"></i> Sales Transactions</button>  </div>  <div style="padding:20px;">  <!-- Tab: Deliveries -->  <div id="tabContentDeliveries" style="max-height:300px;overflow-y:auto;border:1px solid #e2e8f0;border-radius:6px;">  <table class="po-table">  <thead>  <tr>  <th>Date</th>  <th>Invoice No.</th>  <th>Supplier</th>  <th style="text-align:right;">Liters</th>  <th>Status</th>  </tr>  </thead>  <tbody id="movDeliveriesBody"></tbody>  </table>  </div>  <!-- Tab: Sales -->  <div id="tabContentSales" style="display:none;max-height:300px;overflow-y:auto;border:1px solid #e2e8f0;border-radius:6px;">  <table class="po-table">  <thead>  <tr>  <th>Date</th>  <th>Shift Period</th>  <th style="text-align:right;">Liters Sold</th>  <th style="text-align:right;">Total Amount</th>  <th>Status</th>  </tr>  </thead>  <tbody id="movSalesBody"></tbody>  </table>  </div>  </div>  </div>  <div class="modal-footer">  <button onclick="closeMovementModal()" class="btn-cancel" style="height:32px;font-size:12px;padding:0 12px;">Close</button>  </div>  </div>
</div>  <script>
function esc(str) {  if (!str) return '';  return str.toString()  .replace(/&/g, "&amp;")  .replace(/</g, "&lt;")  .replace(/>/g, "&gt;")  .replace(/"/g, "&quot;")  .replace(/'/g, "&#039;");
}  function filterFuelTable() {  var search = document.getElementById('fuelSearch').value.toLowerCase();  var type = document.getElementById('fuelTypeFilter').value.toLowerCase();  var status = document.getElementById('fuelStatusFilter').value.toLowerCase();  var rows = document.querySelectorAll('#fuelTableBody tr.fuel-row');  rows.forEach(function(row) {  var match = true;  var rName = row.dataset.name || '';  var rDesc = row.dataset.desc || '';  var rType = row.dataset.type || '';  var rStatus = row.dataset.status || '';  if (search && rName.indexOf(search) === -1 && rDesc.indexOf(search) === -1 && rType.indexOf(search) === -1) {  match = false;  }  if (type && rType !== type) {  match = false;  }  if (status && rStatus !== status) {  match = false;  }  if (match) {  row.classList.remove('search-hidden');  row.style.display = '';  } else {  row.classList.add('search-hidden');  row.style.display = 'none';  }  });  // Re-sync pagination after filter changes  if (typeof setTablePage === 'function') {  setTablePage('mgrFuelTable', 1);  }
}  // ── Tank Details Modal Functions ──
function viewTankDetails(r) {  document.getElementById('detTankId').textContent = r.tank_id;  document.getElementById('detTankName').textContent = r.tank_name;  document.getElementById('detTankDesc').textContent = r.tank_description;  document.getElementById('detFuelType').textContent = r.fuel_type;  document.getElementById('detCapacity').textContent = Number(r.capacity).toLocaleString() + ' L';  document.getElementById('detVolume').textContent = Number(r.current_volume).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' L';  document.getElementById('detRemaining').textContent = Number(r.remaining_capacity).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' L';  var statusSpan = '<span class="inv-stock-badge" style="background:' + r.status_color + '20;color:' + r.status_color + ';border:1px solid ' + r.status_color + '40;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:700;text-transform:uppercase;">' + r.status + '</span>';  document.getElementById('detStatus').innerHTML = statusSpan;  var ts = r.last_updated ? new Date(r.last_updated).toLocaleString() : '—';  document.getElementById('detUpdated').textContent = ts;  document.getElementById('tankModal').classList.add('open');
}  function closeTankModal() {  document.getElementById('tankModal').classList.remove('open');
}  // ── Fuel Movement Modal Functions ──
var currentMovTab = 'deliveries';
function viewFuelMovement(fuelType, tankName) {  document.getElementById('movementModalTitle').textContent = 'Movement History — ' + tankName + ' (' + fuelType + ')';  var delBody = document.getElementById('movDeliveriesBody');  var salesBody = document.getElementById('movSalesBody');  delBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:24px;color:#64748b;"><i class="fas fa-spinner fa-spin"></i> Loading deliveries...</td></tr>';  salesBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:24px;color:#64748b;"><i class="fas fa-spinner fa-spin"></i> Loading sales...</td></tr>';  document.getElementById('movementModal').classList.add('open');  switchMovTab('deliveries');  fetch('manager_inventory_fuel.php?ajax=1&action=get_fuel_details&fuel_type=' + encodeURIComponent(fuelType))  .then(function(r) { return r.json(); })  .then(function(res) {  if (!res.success) {  delBody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:#dc3545;">Failed to load data.</td></tr>';  salesBody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:#dc3545;">Failed to load data.</td></tr>';  return;  }  // Render Deliveries  if (res.deliveries.length === 0) {  delBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:12px;color:#94a3b8;">No recent deliveries recorded.</td></tr>';  } else {  var delHtml = '';  res.deliveries.forEach(function(d) {  var dateStr = d.delivery_date ? new Date(d.delivery_date).toLocaleDateString() : '—';  var statusCls = d.status === 'Verified' ? 'background:#e6f4ea;color:#28a745;border:1px solid #c3e6cb;' : 'background:#f1f5f9;color:#475569;border:1px solid #cbd5e1;';  delHtml += '<tr>' +  '<td>' + dateStr + '</td>' +  '<td><code>' + esc(d.invoice_no || '—') + '</code></td>' +  '<td>' + esc(d.supplier || '—') + '</td>' +  '<td style="text-align:right;font-weight:700;color:#002F70;">' + Number(d.delivery_liters).toLocaleString() + ' L</td>' +  '<td><span style="font-size:10px;font-weight:700;padding:2px 6px;border-radius:4px;' + statusCls + '">' + esc(d.status) + '</span></td>' +  '</tr>';  });  delBody.innerHTML = delHtml;  }  // Render Sales  if (res.transactions.length === 0) {  salesBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:12px;color:#94a3b8;">No recent sales transactions.</td></tr>';  } else {  var salesHtml = '';  res.transactions.forEach(function(t) {  var dateStr = t.transaction_date ? new Date(t.transaction_date).toLocaleDateString() + ' ' + new Date(t.transaction_date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '—';  var statusCls = t.status === 'Verified' ? 'background:#e6f4ea;color:#28a745;border:1px solid #c3e6cb;' : 'background:#f1f5f9;color:#475569;border:1px solid #cbd5e1;';  salesHtml += '<tr>' +  '<td>' + dateStr + '</td>' +  '<td>' + esc(t.shift_period || '—') + '</td>' +  '<td style="text-align:right;font-weight:700;color:#002F70;">' + Number(t.liters_sold).toLocaleString() + ' L</td>' +  '<td style="text-align:right;font-weight:600;">₱' + Number(t.total_amount).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + '</td>' +  '<td><span style="font-size:10px;font-weight:700;padding:2px 6px;border-radius:4px;' + statusCls + '">' + esc(t.status) + '</span></td>' +  '</tr>';  });  salesBody.innerHTML = salesHtml;  }  })  .catch(function() {  delBody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:#dc3545;">Connection error.</td></tr>';  salesBody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:#dc3545;">Connection error.</td></tr>';  });
}  function closeMovementModal() {  document.getElementById('movementModal').classList.remove('open');
}  function switchMovTab(tab) {  currentMovTab = tab;  var delBtn = document.getElementById('tabDelBtn');  var salesBtn = document.getElementById('tabSalesBtn');  var delContent = document.getElementById('tabContentDeliveries');  var salesContent = document.getElementById('tabContentSales');  if (tab === 'deliveries') {  delBtn.style.color = '#002F70';  delBtn.style.borderBottomColor = '#002F70';  salesBtn.style.color = '#64748b';  salesBtn.style.borderBottomColor = 'transparent';  delContent.style.display = 'block';  salesContent.style.display = 'none';  } else {  salesBtn.style.color = '#002F70';  salesBtn.style.borderBottomColor = '#002F70';  delBtn.style.color = '#64748b';  delBtn.style.borderBottomColor = 'transparent';  salesContent.style.display = 'block';  delContent.style.display = 'none';  }
}  // ── Print Tank Record Function ──
