ank_description) + '</td></tr>');  pw.document.write('<tr><td>Fuel Type:</td><td><strong>' + esc(r.fuel_type) + '</strong></td></tr>');  pw.document.write('</table></div>');  pw.document.write('<div class="section"><h4>Inventory & Capacity Status</h4>');  pw.document.write('<table class="info">');  pw.document.write('<tr><td>Tank Capacity:</td><td>' + Number(r.capacity).toLocaleString() + ' L</td></tr>');  pw.document.write('<tr><td>Current Volume:</td><td><strong style="font-size:14px;color:#002F70;">' + Number(r.current_volume).toLocaleString('en-US', {minimumFractionDigits: 2}) + ' L</strong></td></tr>');  pw.document.write('<tr><td>Remaining Capacity:</td><td>' + Number(r.remaining_capacity).toLocaleString('en-US', {minimumFractionDigits: 2}) + ' L</td></tr>');  pw.document.write('<tr><td>Status:</td><td><span class="badge" style="background:' + r.status_color + '20;color:' + r.status_color + ';border:1px solid ' + r.status_color + '40;">' + r.status + '</span></td></tr>');  pw.document.write('<tr><td>Last Updated:</td><td>' + (r.last_updated ? new Date(r.last_updated).toLocaleString() : '—') + '</td></tr>');  pw.document.write('</table></div>');  pw.document.write('<div class="footer">Petron Station Management System &copy; ' + new Date().getFullYear() + '</div>');  pw.document.write('</body></html>');  pw.document.close();  pw.print();
