}  function exportFuelTableCSV() {  var rows = document.querySelectorAll('#mgrFuelTable tr');  var csv = [];  rows.forEach(function(row) {  if (row.style.display === 'none') return;  var cells = row.querySelectorAll('td, th');  var data = [];  cells.forEach(function(cell) {  var text = cell.innerText.trim().replace(/"/g, '""');  data.push('"' + text + '"');  });  if (data.length) csv.push(data.join(','));  });  var blob = new Blob([csv.join('\n')], {type: 'text/csv'});  var a = document.createElement('a');  a.href = URL.createObjectURL(blob);  a.download = 'fuel_tanks_overview_' + new Date().toISOString().slice(0,10) + '.csv';  document.body.appendChild(a);  a.click();  document.body.removeChild(a);
