function filterAlertTable() {  var search  = (document.getElementById('alertSearch') || {}).value || '';  var ftype  = (document.getElementById('alertTypeFilter') || {}).value || '';  var severity = (document.getElementById('alertSeverityFilter') || {}).value || '';  search  = search.toLowerCase();  ftype  = ftype.toLowerCase();  severity = severity.toLowerCase();  document.querySelectorAll('#alertTableBody tr.alert-row').forEach(function(row) {  var name  = (row.dataset.name  || '').toLowerCase();  var desc  = (row.dataset.desc  || '').toLowerCase();  var type  = (row.dataset.type  || '').toLowerCase();  var alert = (row.dataset.alert || '').toLowerCase();  var ok = true;  if (search  && name.indexOf(search) === -1 && desc.indexOf(search) === -1 && type.indexOf(search) === -1) ok = false;  if (ftype  && type  !== ftype)  ok = false;  if (severity && alert  !== severity) ok = false;  row.style.display = ok ? '' : 'none';  });
