mation</h4>');  pw.document.write('<table class="info">');  pw.document.write('<tr><td>Tank Name:</td><td><strong>' + esc(r.tank_name) + '</strong></td></tr>');  pw.document.write('<tr><td>Location:</td><td>' + esc(r.tank_description) + '</td></tr>');  pw.document.write('<tr><td>Fuel Type:</td><td><strong>' + esc(r.fuel_type) + '</strong></td></tr>');  pw.document.write('</table></div>');  pw.document.write('<div class="section"><h4>Alert Details</h4>');  pw.document.write('<div class="alert-box">' + esc(r.alert_type) + ': ' + esc(r.recommended_action) + '</div>');  pw.document.write('<table class="info">');  pw.document.write('<tr><td>Current Volume:</td><td><strong style="color:#002F70;font-size:14px;">' + Number(r.current_volume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L</strong></td></tr>');  pw.document.write('<tr><td>Tank Capacity:</td><td>' + Number(r.capacity).toLocaleString() + ' L</td></tr>');  pw.document.write('<tr><td>Reorder Level:</td><td>' + (r.reorder_level ? Number(r.reorder_level).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L' : '—') + '</td></tr>');  pw.document.write('<tr><td>Last Updated:</td><td>' + (r.last_updated ? new Date(r.last_updated).toLocaleString() : '—') + '</td></tr>');  pw.document.write('</table></div>');  pw.document.write('<div class="footer">Petron Station Management System &copy; ' + new Date().getFullYear() + '</div>');  pw.document.write('</body></html>');  pw.document.close();  pw.print();
