var _fuelReqData = {};
function openCreateFuelRequest(fuelType, currentVolume, capacity, alertType) {  _fuelReqData = { fuel_type: fuelType, current_level: currentVolume, capacity: capacity, stock_status: alertType.toUpperCase() };  document.getElementById('frFuelType').textContent  = fuelType;  document.getElementById('frCurrentVol').textContent  = Number(currentVolume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L';  document.getElementById('frCapacity').textContent  = Number(capacity).toLocaleString() + ' L';  document.getElementById('frAlertType').textContent  = alertType;  document.getElementById('frAlertType').style.color  = alertType === 'Empty Tank' ? '#000' : (alertType === 'Critical Fuel' ? '#dc3545' : '#fd7e14');  var suggested = Math.max(0, capacity - currentVolume);  document.getElementById('frRequestedLiters').value  = suggested.toFixed(2);  document.getElementById('frRemarks').value  = '';  document.getElementById('frResultMsg').style.display = 'none';  document.getElementById('frSubmitBtn').disabled  = false;  document.getElementById('frSubmitBtn').innerHTML  = '<i class="fas fa-paper-plane"></i> Submit Request';  document.getElementById('createFuelRequestModal').classList.add('open');
}  function closeCreateFuelRequest() {  document.getElementById('createFuelRequestModal').classList.remove('open');
}  document.addEventListener('DOMContentLoaded', function() {  var form = document.getElementById('createFuelRequestForm');  if (form) {  form.addEventListener('submit', function(e) {  e.preventDefault();  var liters = parseFloat(document.getElementById('frRequestedLiters').value);  if (!liters || liters <= 0) {  alert('Please enter a valid requested liters amount.');  return;  }  var btn = document.getElementById('frSubmitBtn');  btn.disabled = true;  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Submitting...';  var payload = {  fuel_type:  _fuelReqData.fuel_type,  current_level:  _fuelReqData.current_level,  capacity:  _fuelReqData.capacity,  stock_status:  _fuelReqData.stock_status,  requested_liters: liters,  remarks:  document.getElementById('frRemarks').value.trim()  };  fetch('../backend/api/fuel_stock_request.php?action=create', {  method:  'POST',  headers: {'Content-Type': 'application/json'},  body:  JSON.stringify(payload)  })  .then(function(r) { return r.json(); })  .then(function(res) {  var msgEl = document.getElementById('frResultMsg');  if (res.success) {  msgEl.innerHTML  = '<i class="fas fa-check-circle" style="color:#28a745;"></i> Request submitted successfully! It is now <strong>Pending</strong> review.';  msgEl.style.background = '#e6f4ea';  msgEl.style.border  = '1px solid #c3e6cb';  msgEl.style.color  = '#155724';  btn.innerHTML = '<i class="fas fa-check"></i> Submitted';  } else {  msgEl.innerHTML  = '<i class="fas fa-exclamation-circle" style="color:#dc3545;"></i> ' + (res.message || 'Submission failed.');  msgEl.style.background = '#fce8e6';  msgEl.style.border  = '1px solid #f5c2c7';  msgEl.style.color  = '#721c24';  btn.disabled  = false;  btn.innerHTML = '<i class="fas fa-paper-plane"></i> Submit Request';  }  msgEl.style.display = 'block';  })  .catch(function() {  var msgEl = document.getElementById('frResultMsg');  msgEl.innerHTML = '<i class="fas fa-exclamation-circle" style="color:#dc3545;"></i> Connection error. Please try again.';  msgEl.style.display = 'block';  btn.disabled  = false;  btn.innerHTML = '<i class="fas fa-paper-plane"></i> Submit Request';  });  });  }  if (typeof setupTablePagination === 'function') {  setupTablePagination('mgrFuelTable', null, 'mgrFuelPagination', 20);  setupTablePagination('mgrMovTable', null, 'mgrMovPagination', 20);  }
});  // ── Movement Table Filter ──
function filterMovTable() {  var search = ((document.getElementById('movSearch') || {}).value || '').toLowerCase();  var fuel  = ((document.getElementById('movFuelFilter') || {}).value || '').toLowerCase();  var type  = ((document.getElementById('movTypeFilter') || {}).value || '').toLowerCase();  document.querySelectorAll('#movTableBody tr.mov-row').forEach(function(row) {  var ok = true;  if (search && (row.dataset.search || '').indexOf(search) === -1) ok = false;  if (fuel  && (row.dataset.fuel  || '') !== fuel)  ok = false;  if (type  && (row.dataset.type  || '').indexOf(type) === -1)  ok = false;  row.style.display = ok ? '' : 'none';  });
}  // ── Movement Details Modal ──
function viewMovDetails(m) {  var typeColor = m.movement_id.startsWith('DEL') ? '#28a745'  : (m.movement_id.startsWith('SAL') ? '#dc3545' : '#6f42c1');  document.getElementById('movDetId').textContent  = m.movement_id;  document.getElementById('movDetDate').textContent = m.movement_date || '—';  document.getElementById('movDetFuel').textContent = m.fuel_type || '—';  document.getElementById('movDetTank').textContent = m.tank || '—';  document.getElementById('movDetType').innerHTML  = '<span style="background:' + typeColor + '20;color:' + typeColor + ';border:1px solid ' + typeColor + '40;padding:3px 10px;border-radius:4px;font-size:11px;font-weight:700;">' + esc(m.movement_type) + '</span>';  var lSign = m.movement_id.startsWith('SAL') ? '-' : (parseFloat(m.liters) >= 0 ? '+' : '');  document.getElementById('movDetLiters').textContent  = lSign + Number(m.liters).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L';  document.getElementById('movDetLiters').style.color  = typeColor;  document.getElementById('movDetPrevVol').textContent  = m.previous_volume != null ? Number(m.previous_volume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L' : '—';  document.getElementById('movDetNewVol').textContent  = m.new_volume != null ? Number(m.new_volume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L' : '—';  document.getElementById('movDetBy').textContent  = m.performed_by || '—';  document.getElementById('movDetRef').textContent  = m.ref_no || '—';  document.getElementById('movDetStatus').textContent  = m.status || '—';  document.getElementById('movDetNotes').textContent  = m.notes || '—';  document.getElementById('movDetailModal').classList.add('open');
}  function closeMovDetailModal() {  document.getElementById('movDetailModal').classList.remove('open');
}  // ── Print Movement Record ──
function printMovRecord(m) {  var typeColor = m.movement_id.startsWith('DEL') ? '#28a745'  : (m.movement_id.startsWith('SAL') ? '#dc3545' : '#6f42c1');  var lSign = m.movement_id.startsWith('SAL') ? '-' : (parseFloat(m.liters) >= 0 ? '+' : '');  var pw = window.open('', '_blank');  pw.document.write('<!DOCTYPE html><html><head><title>Movement Record — ' + esc(m.movement_id) + '</title>');  pw.document.write('<style>');  pw.document.write('body{font-family:Arial,sans-serif;font-size:13px;color:#222;margin:0;padding:24px;}');  pw.document.write('.header{background:#002F6C;color:#fff;padding:16px 20px;border-radius:6px 6px 0 0;}');  pw.document.write('.header h2{margin:0;font-size:16px;} .header p{margin:4px 0 0;font-size:11px;opacity:.8;}');  pw.document.write('.section{border:1px solid #e2e8f0;border-top:none;padding:16px 20px;margin-bottom:12px;}');  pw.document.write('.section h4{margin:0 0 10px;color:#002F6C;font-size:11px;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid #e2e8f0;padding-bottom:6px;}');  pw.document.write('table.info{width:100%;border-collapse:collapse;font-size:12px;}');  pw.document.write('table.info td:first-child{color:#64748b;font-weight:600;width:180px;padding:5px 0;}');  pw.document.write('table.info td{padding:5px 0;border-bottom:1px solid #f1f5f9;}');  pw.document.write('.badge{display:inline-block;padding:3px 10px;border-radius:4px;font-size:11px;font-weight:700;}');  pw.document.write('.footer{text-align:center;font-size:10px;color:#94a3b8;margin-top:20px;border-top:1px solid #e2e8f0;padding-top:10px;}');  pw.document.write('</style></head><body>');  pw.document.write('<div class="header"><h2>Fuel Movement Record</h2><p>Petron Station Management System &mdash; Printed: ' + new Date().toLocaleString() + '</p></div>');  pw.document.write('<div class="section"><h4>Movement Information</h4><table class="info">');  pw.document.write('<tr><td>Movement ID:</td><td><strong>' + esc(m.movement_id) + '</strong></td></tr>');  pw.document.write('<tr><td>Date:</td><td>' + esc(m.movement_date) + '</td></tr>');  pw.document.write('<tr><td>Fuel Type:</td><td><strong>' + esc(m.fuel_type) + '</strong></td></tr>');  pw.document.write('<tr><td>Tank / Source:</td><td>' + esc(m.tank) + '</td></tr>');  pw.document.write('<tr><td>Movement Type:</td><td><span class="badge" style="background:' + typeColor + '20;color:' + typeColor + ';border:1px solid ' + typeColor + '40;">' + esc(m.movement_type) + '</span></td></tr>');  pw.document.write('<tr><td>Liters:</td><td><strong style="font-size:14px;color:' + typeColor + ';">' + lSign + Number(m.liters).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L</strong></td></tr>');  pw.document.write('<tr><td>Previous Volume:</td><td>' + (m.previous_volume != null ? Number(m.previous_volume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L' : '—') + '</td></tr>');  pw.document.write('<tr><td>New Volume:</td><td>' + (m.new_volume != null ? Number(m.new_volume).toLocaleString('en-US',{minimumFractionDigits:2}) + ' L' : '—') + '</td></tr>');  pw.document.write('<tr><td>Performed By:</td><td>' + esc(m.performed_by) + '</td></tr>');  pw.document.write('<tr><td>Reference No.:</td><td>' + esc(m.ref_no || '—') + '</td></tr>');  pw.document.write('<tr><td>Status:</td><td>' + esc(m.status || '—') + '</td></tr>');  pw.document.write('<tr><td>Notes:</td><td>' + esc(m.notes || '—') + '</td></tr>');  pw.document.write('</table></div>');  pw.document.write('<div class="footer">Petron Station Management System &copy; ' + new Date().getFullYear() + '</div>');  pw.document.write('</body></html>');  pw.document.close();  pw.print();
}  // ── Movement Export Functions ──
function exportMovTablePDF() {  if (typeof exportTableToPDF === 'function') {  exportTableToPDF('mgrMovTable', 'Fuel Movement History Report');  } else { window.print(); }
}
function exportMovTableExcel() {  if (typeof exportTableToExcel === 'function') {  exportTableToExcel('mgrMovTable', 'fuel_movement_history.xls');  } else { alert('Excel export not supported.'); }
}
function exportMovTableCSV() {  var rows = document.querySelectorAll('#mgrMovTable tr');  var csv  = [];  rows.forEach(function(row) {  var cells = row.querySelectorAll('td, th');  var data  = [];  cells.forEach(function(cell, idx) {  if (idx === cells.length - 1) return;  data.push('"' + cell.innerText.trim().replace(/"/g,'""') + '"');  });  if (data.length) csv.push(data.join(','));  });  var blob = new Blob([csv.join('\n')], {type:'text/csv'});  var a = document.createElement('a');  a.href = URL.createObjectURL(blob);  a.download = 'fuel_movement_history_' + new Date().toISOString().slice(0,10) + '.csv';  document.body.appendChild(a); a.click(); document.body.removeChild(a);
}
