adding:9px 12px;border:1px solid #cbd5e1;border-radius:6px;font-size:13px;resize:vertical;box-sizing:border-box;"  placeholder="Additional notes for the delivery request..."></textarea>  </div>  <div id="frResultMsg" style="display:none;padding:10px 14px;border-radius:6px;font-size:13px;margin-bottom:14px;"></div>  <div style="display:flex;gap:10px;justify-content:flex-end;">  <button type="button" onclick="closeCreateFuelRequest()" class="btn-cancel" style="height:36px;font-size:13px;padding:0 16px;">Cancel</button>  <button type="submit" id="frSubmitBtn" style="background:#002F70;color:#fff;border:none;border-radius:6px;padding:0 20px;height:36px;font-size:13px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px;">  <i class="fas fa-paper-plane"></i> Submit Request  </button>  </div>  </form>  </div>  </div>
